JOIN public.constituency_versions cv ON cv.constituency_internal_id = c.internal_id AND cv.is_current = true
JOIN public.parliamentary_constituencies pc ON pc.code = m.pc_code
JOIN public.parliamentary_constituency_versions pcv ON pcv.pc_id = pc.id AND pcv.is_current = true
